/**
 * Remove a leading copy of the tool name from a description.
 *
 * The catalog was generated by concatenating `name + description`, which
 * produced several shapes:
 *   "Accept All Changes in Word" + "Accept all tracked changes ..."
 *   "Accept All Changes in WordAccept all tracked changes ..."   (no separator)
 *   "Combine PDF" + "Combine PDF files ..."                     (doubled name)
 *
 * Rules, chosen so the operation is idempotent:
 *   - doubled name  -> drop exactly one copy (the description started with
 *                      the name itself)
 *   - hard seam     -> the name runs straight into an upper-case letter
 *   - spaced seam   -> the name is followed by whitespace and the remainder
 *                      starts a new sentence
 * A name that is merely the prefix of a longer word, or that is followed by
 * a lower-case continuation (a predicate that needs the name as its
 * subject), is never damaged.
 *
 * @param {string} description
 * @param {string} name
 * @returns {string} the description without the glued name
 */
export function deglue(description, name) {
  if (typeof description !== "string" || typeof name !== "string" || !name) return description;
  if (!description.startsWith(name)) return description;

  // The description itself began with the name: drop exactly one copy.
  if (description.startsWith(name + name)) {
    return description.slice(name.length);
  }

  let rest = description.slice(name.length);
  if (rest === "") return description;

  const lead = rest[0];
  const hardSeam = !/\s/.test(lead) && /\p{Lu}/u.test(lead);
  const spacedSeam = /\s/.test(lead) && /^\p{Lu}/u.test(rest.trimStart());

  if (!hardSeam && !spacedSeam) return description;

  rest = rest.trimStart();
  if (rest === "") return description;

  // Re-capitalise a lower-case sentence start.
  rest = rest.replace(/^(\p{Ll})/u, (c) => c.toUpperCase());
  return rest;
}

/**
 * A description whose name fragment was glued in with the words in the
 * opposite order ("Kalender 2026" + "frei druckbar ..." became
 * "2026 Kalenderfrei druckbar ...").
 *
 * @param {string} description
 * @param {string} name
 * @returns {boolean}
 */
export function hasReversedNameSeam(description, name) {
  if (typeof description !== "string" || typeof name !== "string") return false;
  const words = name.split(/\s+/).filter(Boolean);
  if (words.length < 2) return false;
  const reversed = [...words].reverse().join(" ");
  if (!description.startsWith(reversed)) return false;
  const lead = description[reversed.length];
  // A space after the fragment means the sentence was simply written that
  // way; a letter means the name was glued onto the first word.
  return Boolean(lead) && !/\s/.test(lead);
}

/**
 * True when the description carries a name that should have been removed.
 *
 * @param {string} description
 * @param {string} name
 * @returns {boolean}
 */
export function isGlued(description, name) {
  if (typeof description !== "string" || typeof name !== "string" || !name) return false;
  if (hasReversedNameSeam(description, name)) return true;
  return deglue(description, name) !== description;
}
